-- Pack be — what has to be done, in Belgium, for a roof photovoltaic project
-- and for an energy community: the templates `tasks.plan()` instantiates
-- when the `tasks` module is installed. The electrical rules and the grid
-- connection are the same in the three regions; planning permits and energy
-- sharing are regional, and a regional template says its region: a project
-- gets those of the regions of its sites.
set search_path = nexgen, public, extensions;

do $$
begin
  if to_regclass('tasks.templates') is null then
    raise notice 'pack be: the tasks module is not installed, its templates are skipped';
    return;
  end if;

  insert into tasks.templates (code, published_by, country, regions, project_kind, phase, role, name, description, legal_source_code, legal_reference, documents, applies_when, depends_on_code, position) values
    -- A photovoltaic installation on an existing roof.
    ('pv_roof_feasibility',        'pack:be', 'BE', '{}',       'pv_roof', 'study',           'owner',         'Feasibility study: yield, self-consumption share, budget',                    'The roof, its orientation and shading, the site''s consumption curve, the expected yield and the share self-consumed, the budget and the return.', null, null, '{"Feasibility report"}', null, null, 10),
    ('pv_roof_design',             'pack:be', 'BE', '{}',       'pv_roof', 'design',          'installer',     'Structural check of the roof and electrical design',                          'The roof carries the arrays; the electrical design (strings, inverter, protections) follows the general regulation on electrical installations and the grid operators'' prescription for production in parallel with the grid.', 'be_arei_livre_1', 'Livre 1', '{"Structural note", "Single-line diagram"}', null, 'pv_roof_feasibility', 20),
    ('pv_roof_permit_vlg',         'pack:be', 'BE', '{BE-VLG}', 'pv_roof', 'permitting',      'owner',         'Planning permit exemption checked for the roof installation (Flanders)',      'Solar panels on a roof need no planning permit in Flanders under the conditions of the exemption order; a protected building or a local regulation may still ask for one.', 'be_vlg_vrijstellingsbesluit', null, '{}', null, 'pv_roof_feasibility', 30),
    ('pv_roof_permit_bru',         'pack:be', 'BE', '{BE-BRU}', 'pv_roof', 'permitting',      'owner',         'Planning permit exemption checked for the roof installation (Brussels)',      'No planning permit when the panels are not visible from the public space, or are set in or parallel to the roof plane without protruding more than 30 cm, and depart from no planning regulation; a permit otherwise.', 'be_bru_minime_importance', null, '{}', null, 'pv_roof_feasibility', 30),
    ('pv_roof_permit_wal',         'pack:be', 'BE', '{BE-WAL}', 'pv_roof', 'permitting',      'owner',         'Planning permit exemption checked for the roof installation (Wallonia)',      'Photovoltaic panels on a roof are among the works that need no planning permit in Wallonia, within the conditions the code sets; a listed building or a local guide may still ask for one.', 'be_wal_codt', 'R.IV.1-1', '{}', null, 'pv_roof_feasibility', 30),
    ('pv_roof_grid_notification',  'pack:be', 'BE', '{}',       'pv_roof', 'grid_connection', 'installer',     'Installation notified to or requested from the distribution operator',        'A small installation is notified to the distribution operator of the site; a larger one is first requested and studied by the operator, following the prescription for production in parallel with the grid.', 'be_synergrid_c10_11', null, '{"Notification or connection request", "Operator''s answer"}', null, 'pv_roof_design', 40),
    ('pv_roof_procurement',        'pack:be', 'BE', '{}',       'pv_roof', 'procurement',     'installer',     'Modules, inverter and mounting system ordered and delivered',                 null, null, null, '{"Order", "Delivery note", "Datasheets"}', null, 'pv_roof_design', 50),
    ('pv_roof_installation',       'pack:be', 'BE', '{}',       'pv_roof', 'installation',    'installer',     'Arrays mounted and wired',                                                    null, null, null, '{"Photos of the installation", "Single-line diagram as built"}', null, 'pv_roof_procurement', 60),
    ('pv_roof_conformity',         'pack:be', 'BE', '{}',       'pv_roof', 'commissioning',   'installer',     'Conformity inspection by an accredited body before use',                     'An accredited inspection body checks the installation against the general regulation on electrical installations before it is put into use, and issues its report with the diagrams.', 'be_arei_livre_1', 'Livre 1', '{"Conformity inspection report", "Single-line and location diagrams"}', null, 'pv_roof_installation', 70),
    ('pv_roof_operator_registered','pack:be', 'BE', '{}',       'pv_roof', 'grid_connection', 'grid_operator', 'Installation registered by the operator and meter set for injection',         'The distribution operator registers the production unit from the notification and the conformity report, and sets the meter of the site to measure the injection.', 'be_synergrid_c10_11', null, '{"Operator''s confirmation"}', null, 'pv_roof_conformity', 80),
    ('pv_roof_handover',           'pack:be', 'BE', '{}',       'pv_roof', 'handover',        'installer',     'Installation handed over with its file',                                      'Diagrams, datasheets, warranties, the conformity inspection report, the monitoring access, handed to the owner.', null, null, '{"Handover file"}', null, 'pv_roof_operator_registered', 90),
    -- An energy community sharing electricity among its members.
    ('ec_perimeter_check',         'pack:be', 'BE', '{}',       'energy_community', 'study',  'community_manager', 'Members, metering points and production of the community listed',          'The candidate members, the EAN of each metering point, the production installations and who owns them; every point must have a meter read every quarter hour.', null, null, '{"List of members", "List of metering points"}', null, null, 10),
    ('ec_vlg_legal_entity',        'pack:be', 'BE', '{BE-VLG}', 'energy_community', 'design', 'community_manager', 'Legal entity founded and notified to the regulator (Flanders)',             'The community is a legal entity, usually a new one; it is notified to the Flemish utility regulator within 30 days of its founding, through the form on the regulator''s website.', 'be_vlg_energiegemeenschappen', null, '{"Statutes", "Notification to the regulator"}', null, 'ec_perimeter_check', 20),
    ('ec_vlg_sharing_agreement',   'pack:be', 'BE', '{BE-VLG}', 'energy_community', 'design', 'community_manager', 'Sharing agreement and allocation key written (Flanders)',                   'The agreement among the members: who shares with whom, the allocation key, the price of the shared energy, entries and exits.', 'be_vlg_energiedecreet', 'Article 7.2.1', '{"Sharing agreement"}', null, 'ec_vlg_legal_entity', 30),
    ('ec_vlg_operator_registered', 'pack:be', 'BE', '{BE-VLG}', 'energy_community', 'grid_connection', 'grid_operator', 'Sharing registered with the distribution operator (Flanders)',          'The distribution operator registers the metering points and the key, and allocates the shared energy every quarter hour.', 'be_vlg_energiedecreet', 'Article 7.2.1', '{"Operator''s confirmation"}', null, 'ec_vlg_sharing_agreement', 60),
    ('ec_bru_legal_entity',        'pack:be', 'BE', '{BE-BRU}', 'energy_community', 'design', 'community_manager', 'Form of the community chosen and legal entity founded (Brussels)',         'A citizen, renewable or local energy community: each form says which activities it may carry out, who may take part and who may control it.', 'be_bru_brugel_guide_ce', null, '{"Statutes"}', null, 'ec_perimeter_check', 20),
    ('ec_bru_authorisation',       'pack:be', 'BE', '{BE-BRU}', 'energy_community', 'permitting', 'regulator',     'Energy community authorised by the regulator (Brussels)',                  'The Brussels regulator authorises the community on its file: form, members, sharing activity, allocation key.', 'be_bru_ordonnance_electricite', 'Article 28sexiesdecies', '{"Authorisation file", "Regulator''s decision"}', null, 'ec_bru_legal_entity', 40),
    ('ec_bru_operator_registered', 'pack:be', 'BE', '{BE-BRU}', 'energy_community', 'grid_connection', 'grid_operator', 'Sharing registered with the distribution operator (Brussels)',          'The distribution operator registers the metering points and the key, and allocates the shared energy every quarter hour.', 'be_bru_ordonnance_electricite', null, '{"Operator''s confirmation"}', null, 'ec_bru_authorisation', 60),
    ('ec_wal_legal_entity',        'pack:be', 'BE', '{BE-WAL}', 'energy_community', 'design', 'community_manager', 'Legal entity founded, sharing activity and allocation key written (Wallonia)', 'The community, its members and its representative, the sharing activity and the allocation key it asks for.', 'be_wal_decret_electricite', 'Articles 35octies to 35quindecies', '{"Statutes", "Mandate of the representative"}', null, 'ec_perimeter_check', 20),
    ('ec_wal_operator_opinion',    'pack:be', 'BE', '{BE-WAL}', 'energy_community', 'permitting', 'grid_operator', 'Technical opinion of the distribution operator (Wallonia)',                'The distribution operator gives its technical opinion on the sharing activity and may propose another allocation key.', 'be_wal_agw_2023_ce', 'Article 20', '{"Operator''s technical opinion"}', null, 'ec_wal_legal_entity', 30),
    ('ec_wal_authorisation',       'pack:be', 'BE', '{BE-WAL}', 'energy_community', 'permitting', 'regulator',     'Sharing activity authorised by the regulator (Wallonia)',                  'The Walloon regulator checks the sharing activity against its conditions after the operator''s opinion and decides; a later change of the activity goes through it again.', 'be_wal_agw_2023_ce', 'Article 20', '{"Regulator''s decision"}', null, 'ec_wal_operator_opinion', 40),
    ('ec_participant_consents',    'pack:be', 'BE', '{}',       'energy_community', 'permitting', 'community_manager', 'Members'' adhesions and consents to the use of their meter data collected', 'Each member adheres to the community and consents to the operator sharing its quarter-hour data with the community.', null, null, '{"Adhesion forms", "Consents"}', null, 'ec_perimeter_check', 50),
    ('ec_monthly_settlement',      'pack:be', 'BE', '{}',       'energy_community', 'operation', 'community_manager', 'Monthly settlement of the shared energy',                                 'Each month, from the operator''s allocated volumes: the shared energy of each member at the agreed price, the producers'' share, what was taken from and given to the grid.', null, null, '{"Settlement statement", "Invoices"}', null, 'ec_participant_consents', 80);
end;
$$;
